package com.markschmidt.scoreboard

import android.content.Context
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey

/**
 * The controller identity: a 32-byte Ed25519 seed, hex-encoded, generated by
 * the core on first launch and persisted so this install's pairings survive.
 *
 * The Android sibling of the iOS Keychain entry. IMPORTANT: this is a NEW
 * controller — the server keeps a per-board allow-list of controller pubkeys,
 * so an Android install pairs itself (the code on the panel), it does not
 * inherit the iPhone's grant.
 */
object Identity {
    private const val STORE = "scoreboard-identity"
    private const val KEY = "secret-seed-hex"

    private fun prefs(context: Context) = EncryptedSharedPreferences.create(
        context,
        STORE,
        MasterKey.Builder(context).setKeyScheme(MasterKey.KeyScheme.AES256_GCM).build(),
        EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
        EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM,
    )

    fun load(context: Context): String? = prefs(context).getString(KEY, null)

    fun save(context: Context, seedHex: String) {
        prefs(context).edit().putString(KEY, seedHex).apply()
    }
}
